def diameter_of_binary_tree(root):
    best = 0

    def height(node):
        nonlocal best
        if not node:
            return 0
        l, r = height(node.left), height(node.right)
        best = max(best, l + r)        # longest path through this node (edges)
        return 1 + max(l, r)

    height(root)
    return best

