from collections import deque

def invert_tree(root):
    queue = deque([root] if root else [])
    while queue:
        node = queue.popleft()
        node.left, node.right = node.right, node.left   # swap, then visit children
        if node.left:
            queue.append(node.left)
        if node.right:
            queue.append(node.right)
    return root

