class Codec:
    def serialize(self, root):
        out = []

        def dfs(node):                 # preorder, '#' for null
            if not node:
                out.append('#')
                return
            out.append(str(node.val))
            dfs(node.left)
            dfs(node.right)

        dfs(root)
        return ','.join(out)

    def deserialize(self, data):
        tokens = iter(data.split(','))  # single cursor

        def build():
            t = next(tokens)
            if t == '#':
                return None
            node = TreeNode(int(t))
            node.left = build()
            node.right = build()
            return node

        return build()

from collections import deque


class Codec:
    def serialize(self, root):
        out, queue = [], deque([root])
        while queue:                   # level order, '#' for null
            node = queue.popleft()
            if node:
                out.append(str(node.val))
                queue.append(node.left)
                queue.append(node.right)
            else:
                out.append('#')
        return ','.join(out)

    def deserialize(self, data):
        tokens = data.split(',')
        if tokens[0] == '#':
            return None
        root = TreeNode(int(tokens[0]))
        queue, i = deque([root]), 1
        while queue:
            node = queue.popleft()
            for side in ('left', 'right'):  # the next two tokens are its children
                if tokens[i] != '#':
                    child = TreeNode(int(tokens[i]))
                    setattr(node, side, child)
                    queue.append(child)
                i += 1
        return root

