def is_subtree(root, sub_root):
    def same(a, b):
        if not a or not b:
            return a is b
        return a.val == b.val and same(a.left, b.left) and same(a.right, b.right)

    if not root:
        return False
    return same(root, sub_root) or is_subtree(root.left, sub_root) or is_subtree(root.right, sub_root)
